# -*- coding: utf-8 -*-
import os, re, shutil, sys
sys.path.insert(0, os.path.dirname(__file__))
from fotos import *
import time as _time
VER = _time.strftime("%Y%m%d%H%M")

OUT = sys.argv[1]
PREVIEW = "preview" in sys.argv[2:]
PALETA = True  # paleta azul marino y verde petróleo elegida por Alex
import json, html as _h
BASE = "https://leypedia.com/"
# Identificadores públicos de Google Analytics y de verificación de buscadores (no son claves secretas)
SEO = json.load(open(os.path.join(os.path.dirname(__file__), "seo.json"), encoding="utf-8"))
HERE = os.path.dirname(__file__)

if os.path.isdir(OUT):
    shutil.rmtree(OUT)
os.makedirs(OUT)

def rel(from_route, to_route):
    depth = from_route.count("/")
    if PREVIEW:
        to_route = to_route + "index.html"
    return ("../" * depth) + to_route if (("../" * depth) + to_route) else "./"

def fill_links(html, lang, route):
    def rep(m):
        k = m.group(1)
        if k == "img":
            return "../" * route.count("/") + "assets/img/"
        if k in ROUTES:
            r = rel(route, ROUTES[k][0 if lang == "es" else 1])
            return r or "./"
        return m.group(0)
    return re.sub(r"\{([a-z]+)\}", rep, html)

def _abs_img(html):
    m = re.search(r'src="\{img\}([^"]+)"', html)
    return BASE + "assets/img/" + (m.group(1) if m else "home-congreso.jpg")

def seo_head(pid, lang, route, p, title):
    es = lang == "es"
    url = BASE + route
    desc = _h.escape(_h.unescape(p["desc"]), quote=True)
    t = _h.escape(_h.unescape(title), quote=True)
    out = [f'<meta name="robots" content="{"noindex, follow" if pid == "buscar" else "index, follow, max-image-preview:large"}">']
    if SEO.get("google"): out.append(f'<meta name="google-site-verification" content="{SEO["google"]}">')
    if SEO.get("bing"): out.append(f'<meta name="msvalidate.01" content="{SEO["bing"]}">')
    if SEO.get("ga"): out.append(f'<meta name="lp-ga" content="{SEO["ga"]}">')
    out += [f'<meta property="og:type" content="{"website" if pid == "home" else "article"}">',
            '<meta property="og:site_name" content="Leypedia">',
            f'<meta property="og:title" content="{t}">', f'<meta property="og:description" content="{desc}">',
            f'<meta property="og:url" content="{url}">', f'<meta property="og:image" content="{_abs_img(p["html"])}">',
            f'<meta property="og:locale" content="{"es_ES" if es else "ca_ES"}">',
            f'<meta property="og:locale:alternate" content="{"ca_ES" if es else "es_ES"}">',
            '<meta name="twitter:card" content="summary_large_image">']
    ld = []
    if pid == "home":
        ld.append({"@context": "https://schema.org", "@type": "WebSite", "name": "Leypedia", "url": url, "inLanguage": lang,
                   "potentialAction": {"@type": "SearchAction", "target": BASE + ROUTES["buscar"][0 if es else 1] + "?q={search_term_string}",
                                       "query-input": "required name=search_term_string"}})
        ld.append({"@context": "https://schema.org", "@type": "Organization", "name": "Leypedia", "url": BASE,
                   "logo": BASE + "assets/favicon.svg"})
    elif p.get("crumbs") is not None:
        items = [("Inicio" if es else "Inici", BASE + ROUTES["home"][0 if es else 1])] + \
                [(_h.unescape(n), BASE + ROUTES[k][0 if es else 1]) for k, n in p["crumbs"] if k in ROUTES] + [(_h.unescape(p["title"]), url)]
        ld.append({"@context": "https://schema.org", "@type": "BreadcrumbList",
                   "itemListElement": [{"@type": "ListItem", "position": i + 1, "name": n, "item": u} for i, (n, u) in enumerate(items)]})
    for x in ld:
        out.append('<script type="application/ld+json">' + json.dumps(x, ensure_ascii=False).replace("</", "<\\/") + '</script>')
    return "\n".join(out)

def page(pid, lang):
    p = PAGES[pid][lang]
    route = ROUTES[pid][0 if lang == "es" else 1]
    alt = ROUTES[pid][1 if lang == "es" else 0]
    ui = UI[lang]
    pre = "../" * route.count("/")
    nav = "".join(
        f'<a href="{{{k}}}"{" aria-current=\"page\"" if (k == pid or PARENT.get(pid) == k) else ""}>{t}</a>'
        for k, t in ui["nav"])
    crumbs = ""
    if p.get("crumbs") is not None:
        cs = [f'<a href="{{home}}">{ui["inicio"]}</a>'] + [f'<a href="{{{k}}}">{t}</a>' for k, t in p["crumbs"]]
        crumbs = f'<div class="wrap"><div class="crumbs">{" › ".join(cs)}</div></div>'
    title = p["title"] if p.get("plain_title") else p["title"] + " · Leypedia"
    legal = " · ".join(f'<a href="{{{k}}}">{t}</a>' for k, t in ui["legal"])
    if SEO.get("ga"):
        legal += f' · <a href="#" data-cookies>{"Configurar cookies" if lang == "es" else "Configurar galetes"}</a>'
    seo = seo_head(pid, lang, route, p, title)
    html = f'''<!doctype html>
<html lang="{lang}"{" data-preview" if PREVIEW else ""}>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>{title}</title>
<meta name="description" content="{p["desc"]}">
<link rel="canonical" href="{BASE}{route}">
<link rel="alternate" hreflang="es" href="{BASE}{ROUTES[pid][0]}">
<link rel="alternate" hreflang="ca" href="{BASE}{ROUTES[pid][1]}">
<link rel="alternate" hreflang="x-default" href="{BASE}{ROUTES[pid][0]}">
<link rel="icon" href="{pre}assets/favicon.svg" type="image/svg+xml">
<link rel="stylesheet" href="{pre}assets/style.css?v={VER}">
<script src="{pre}assets/app.js?v={VER}" defer></script>
{seo}
</head>
<body class="p-{pid}">
<header class="top"><div class="hbar"><div class="wrap">
<a class="brand" href="{{home}}"><svg class="logo" aria-hidden="true" width="34" height="34" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" stroke="#152F3C" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata><rect x="1.5" y="1.5" width="61" height="61" rx="14" fill="#E6F4F1" stroke="none"/><path d="M32 13v36M20 49h24M16 20h32"/><path d="M16 20l-7 15h14zM48 20l-7 15h14z" stroke="#08786E"/><path d="M9 35a7 4 0 0 0 14 0M41 35a7 4 0 0 0 14 0" stroke="#08786E"/><circle cx="32" cy="13" r="2.5" fill="#152F3C"/></svg><span class="wm">Ley<span>pedia</span></span></a>
{searchbox(lang)}
<a class="langlink" href="{rel(route, alt)}" hreflang="{ui["otra_l"]}" lang="{ui["otra_l"]}">{ui["otra"]}</a>
</div></div>
<nav class="main" aria-label="{"Secciones" if lang=="es" else "Seccions"}"><div class="wrap">{nav}</div></nav>
</header>
<main>
{crumbs}
{p["html"]}
</main>
<footer><div class="wrap">
<div><p>{ui["aviso"]}</p><p>{ui["fuentes"]}</p></div>
<div><p>{legal}</p><p>© 2026 Leypedia</p></div>
</div></footer>
</body>
</html>
'''
    html = fill_links(html, lang, route)
    d = os.path.join(OUT, route)
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, "index.html"), "w", encoding="utf-8") as f:
        f.write(html)
    txt = re.sub(r"<[^>]+>", " ", p["html"])
    txt = re.sub(r"\s+", " ", _h.unescape(txt)).strip()
    INDEX[lang].append({"t": p["title"], "d": _h.unescape(p["desc"]), "u": route, "a": ambitos(pid, p["html"]), "x": txt[:5000]})
    return route

INDEX = {"es": [], "ca": []}
routes = []
for pid in ROUTES:
    if pid not in PAGES:
        continue
    for lang in ("es", "ca"):
        routes.append(page(pid, lang))

# assets
os.makedirs(os.path.join(OUT, "assets"))
css = open(os.path.join(HERE, "base.css"), encoding="utf-8").read()
css = css.replace('--f-display:"Spectral", Georgia, "Times New Roman", serif;', '--f-display:"Iowan Old Style","Palatino Linotype","Book Antiqua",Palatino,Georgia,serif;')
css = css.replace('--f-body:"IBM Plex Sans", system-ui, -apple-system, "Segoe UI", sans-serif;', '--f-body:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;')
css = css.replace('--f-mono:"IBM Plex Mono", ui-monospace, Menlo, Consolas, monospace;', '--f-mono:ui-monospace,"SFMono-Regular",Menlo,Consolas,monospace;')
css += open(os.path.join(HERE, "extra.css"), encoding="utf-8").read()
css += open(os.path.join(HERE, "extra2.css"), encoding="utf-8").read()
if PALETA:
    css += open(os.path.join(HERE, "paleta.css"), encoding="utf-8").read()
css += open(os.path.join(HERE, "design3.css"), encoding="utf-8").read()
open(os.path.join(OUT, "assets/style.css"), "w", encoding="utf-8").write(css)
shutil.copy(os.path.join(HERE, "app.js"), os.path.join(OUT, "assets/app.js"))
open(os.path.join(OUT, "assets/favicon.svg"), "w").write('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" stroke="#152F3C" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata><rect x="1.5" y="1.5" width="61" height="61" rx="14" fill="#E6F4F1" stroke="none"/><path d="M32 13v36M20 49h24M16 20h32"/><path d="M16 20l-7 15h14zM48 20l-7 15h14z" stroke="#08786E"/><path d="M9 35a7 4 0 0 0 14 0M41 35a7 4 0 0 0 14 0" stroke="#08786E"/><circle cx="32" cy="13" r="2.5" fill="#152F3C"/></svg>')

shutil.copytree(os.path.join(HERE, "img"), os.path.join(OUT, "assets/img"))
for L in ("es", "ca"):
    INDEX[L] = [x for x in INDEX[L] if x["u"] not in ("buscar/", "ca/cercar/")]
    json.dump(INDEX[L], open(os.path.join(OUT, f"assets/buscar-{L}.json"), "w", encoding="utf-8"), ensure_ascii=False, separators=(",", ":"))

# api
os.makedirs(os.path.join(OUT, "api/cache"))
shutil.copy(os.path.join(HERE, "boe.php"), os.path.join(OUT, "api/boe.php"))
shutil.copy(os.path.join(HERE, "feed.php"), os.path.join(OUT, "api/feed.php"))
shutil.copy(os.path.join(HERE, "actualizar.php"), os.path.join(OUT, "api/actualizar.php"))
open(os.path.join(OUT, "api/cache/.htaccess"), "w").write("Require all denied\n")
open(os.path.join(OUT, "api/cache/.gitkeep"), "w").write("")
shutil.copy(os.path.join(HERE, "htaccess"), os.path.join(OUT, ".htaccess"))

# sitemap / robots
HOY = _time.strftime("%Y-%m-%d")
def _sm(pid, L):
    a, b = ROUTES[pid]
    return (f"  <url><loc>{BASE}{a if L == 'es' else b}</loc><lastmod>{HOY}</lastmod>"
            f'<xhtml:link rel="alternate" hreflang="es" href="{BASE}{a}"/><xhtml:link rel="alternate" hreflang="ca" href="{BASE}{b}"/>'
            f'<xhtml:link rel="alternate" hreflang="x-default" href="{BASE}{a}"/></url>\n')
sm = ('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'
      + "".join(_sm(pid, L) for pid in ROUTES if pid in PAGES and pid not in ("buscar",) for L in ("es", "ca")) + "</urlset>\n")
open(os.path.join(OUT, "sitemap.xml"), "w").write(sm)
open(os.path.join(OUT, "robots.txt"), "w").write(f"User-agent: *\nDisallow: /api/\nSitemap: {BASE}sitemap.xml\n")
if SEO.get("indexnow"):
    open(os.path.join(OUT, SEO["indexnow"] + ".txt"), "w").write(SEO["indexnow"])
print(len(routes), "páginas")
